-- Dansk portion 6 del 3/3: 166 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 6591-9984.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish6'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish6', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":6591,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Skriv din ___ på kuverten, så brevet kan komme tilbage.'","o":["addresse","adrese","adresse","addrese"],"a":"adresse","r":"På dansk er der ét d og dobbelt-s. På engelsk er der to d'er, og det forvirrer mange."},
{"l":6617,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"I hvilken bydel i København voksede Tove Ditlevsen op?","o":["Hellerup","Valby","Amager","Vesterbro"],"a":"Vesterbro","r":"Tove Ditlevsen voksede op på Vesterbro i en arbejderfamilie, og kvarteret har stor plads i hendes forfatterskab."},
{"l":6633,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Umiddelbart virker opgaven let.' Hvad betyder 'umiddelbart' i denne sætning?","o":["ved første øjekast","efter grundig overvejelse","helt uden tvivl","om et øjeblik"],"a":"ved første øjekast","r":"Her fortæller ordet om det første indtryk, som måske ændrer sig. I andre sætninger kan det betyde 'straks'."},
{"l":6656,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Alle har ret til at ytre sig.' Hvad har alle ret til?","o":["at stemme til valg","at sige deres mening","at blive lyttet til","at bevæge sig frit"],"a":"at sige deres mening","r":"At ytre sig er at udtrykke sig i tale eller skrift. Deraf kommer ordet ytringsfrihed."},
{"l":6675,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Vi gik forbi de nyligt ___ vægge.'?","o":["malet","male","malede","maler"],"a":"malede","r":"Kort tillægsform bøjes som et tillægsord. Foran et navneord i flertal hedder det 'malede', ikke 'malet'."},
{"l":6697,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Politiet fandt flere ___ cykler i skuret.'?","o":["stjålet","stjæle","stjal","stjålne"],"a":"stjålne","r":"Foran et navneord i flertal hedder kort tillægsform af 'stjæle' 'stjålne'. På samme måde hedder det 'skrevne' og 'fundne'."},
{"l":6708,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvordan staves ordet her? 'Skriv dit navn i den øverste ___ på skemaet.'","o":["rubrik","rubbrik","rubrick","rybrik"],"a":"rubrik","r":"Ordet har ét b og slutter på -ik uden c."},
{"l":6734,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Hvilken ___ fik du for din stil?'","o":["karrakter","karakter","karackter","kharakter"],"a":"karakter","r":"Ordet staves ka-rak-ter med kun k'er, selvom det stammer fra græsk."},
{"l":6753,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Mange jordskælv skyldes 'pladetektonik'. Hvad er det, der flytter sig?","o":["de varme strømme i havet","skyerne højt oppe i luften","store plader i jordskorpen","Månens bane om Jorden"],"a":"store plader i jordskorpen","r":"Jordskorpen består af plader, der bevæger sig langsomt. Hvor de støder sammen eller gnider mod hinanden, kan der komme jordskælv."},
{"l":6774,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord skal stå: 'Vi flyttede til et ___ hus sidste sommer.'?","o":["anden","andre","andens","andet"],"a":"andet","r":"'Hus' er et intetkønsord i ental, så det hedder 'et andet hus'. 'Anden' er fælleskøn, og 'andre' er flertal."},
{"l":6796,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord er et låneord fra engelsk: 'Vi holdt et kort møde i weekenden om festen.'?","o":["weekenden","møde","kort","festen"],"a":"weekenden","r":"'Weekend' er lånt fra engelsk og har beholdt sin engelske stavemåde."},
{"l":6806,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Journalisten valgte en ny vinkel på historien.' Hvad menes der med 'vinkel'?","o":["et tal i grader mellem to rette linjer","den side af sagen, historien handler om","datoen for artiklens udgivelse","prisen for at trykke artiklen"],"a":"den side af sagen, historien handler om","r":"Samme sag kan fortælles på mange måder. Vinklen er det, journalisten vælger at sætte fokus på."},
{"l":6827,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Der var otte sekunder tilbage, og stillingen var 24-24. Ingen på tilskuerpladserne sad ned længere. Træneren var holdt op med at råbe og tyggede bare på sit tyggegummi. Da Aisha løftede armen for at skyde, holdt hele hallen vejret.' Hvilken stemning er der i hallen?","o":["Der er faldet ro på, fordi træneren er holdt op med at råbe.","Alle er skuffede over, at kampen ender uafgjort.","Alle er spændte på, om skuddet går ind.","Alle jubler, fordi Aisha lige har scoret det sidste mål."],"a":"Alle er spændte på, om skuddet går ind.","r":"Folk står op og holder vejret, fordi kampen bliver afgjort nu. Det er ikke ro, men spænding, når hele hallen bliver stille."},
{"l":6851,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hun tog nederlaget med 'olympisk ro'. Hvordan reagerede hun?","o":["hun blev meget vred og råbte op","hun krævede en ny kamp straks","hun gik hjem uden at sige farvel","hun tog det helt roligt"],"a":"hun tog det helt roligt","r":"Udtrykket hentyder til de græske guder på bjerget Olympen, der så ophøjet ned på menneskenes verden."},
{"l":6871,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Find genstandsleddet: 'Den nye bog har jeg allerede læst.'","o":["Den nye bog","jeg","har","allerede"],"a":"Den nye bog","r":"Spørg: Hvad har jeg læst? Selv om leddet står først i sætningen, er det et genstandsled. 'Jeg' er grundled."},
{"l":6891,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket navneord er dannet af tillægsordet 'præcis'?","o":["præcisere","præcision","præcist","præcise"],"a":"præcision","r":"Endelsen -ion danner navneord af mange fremmedord. 'Præcisere' er et udsagnsord, og de to andre er bøjninger af tillægsordet."},
{"l":6904,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Det er bare en vase, sagde mor og fejede skårene sammen. Hun fejede meget længe, også dér, hvor der ikke var nogen skår.' Hvad afslører hendes handling?","o":["At hun er bange for at træde på et skår","At hun er vred på den, der tabte vasen","At vasen betød mere, end hun siger","At hun er meget grundig med rengøring"],"a":"At vasen betød mere, end hun siger","r":"Hun bliver ved, hvor der intet er at feje. Handlingen modsiger 'bare en vase' og viser en følelse, hun ikke siger højt."},
{"l":6928,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Avisen skriver, at landet er i 'recession'. Hvad er det?","o":["en periode med kraftigt økonomisk opsving","en modtagelse med taler og kransekage","en skriftlig bedømmelse af en bog","en periode med økonomisk tilbagegang"],"a":"en periode med økonomisk tilbagegang","r":"I en recession falder produktionen i samfundet. Ordet må ikke forveksles med reception, som er en modtagelse."},
{"l":6948,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Forslaget om at lukke Vestre Bad har fået 1.200 underskrifter imod. Borgmesteren siger: Vi lytter til borgerne, men tallene er, som de er.' Hvad antyder borgmesterens svar?","o":["At underskrifterne nok ikke ændrer noget","At borgerne får badet gratis fremover","At der bør samles flere underskrifter","At tallene for underskrifter er forkerte"],"a":"At underskrifterne nok ikke ændrer noget","r":"Efter 'men' siger borgmesteren, at tallene er, som de er. Det er ikke et direkte nej, men det lyder ikke, som om underskrifterne gør en forskel."},
{"l":6970,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om vintervejret indeholder en relativsætning?","o":["Vi blev hjemme, fordi det sneede.","Den sne, der faldt i nat, er væk.","Hun sagde, at det ville sne i nat.","Hvis det sner, tager vi kælken."],"a":"Den sne, der faldt i nat, er væk.","r":"'Der faldt i nat' siger noget nærmere om navneordet 'sne', og det er relativsætningens opgave."},
{"l":6992,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad angiver ledsætningen i: 'Vi løb, for at vi ikke skulle komme for sent.'?","o":["tid","betingelse","formål","indrømmelse"],"a":"formål","r":"'For at' fortæller, hvad meningen med handlingen er. Ledsætningen angiver altså et formål."},
{"l":7007,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilken form passer? 'Hun var ___ over, at turen blev aflyst.'","o":["skufet","skuffed","skuft","skuffet"],"a":"skuffet","r":"Ordet har dobbelt-f, og tillægsformen ender på -et."},
{"l":7025,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi spiste i stilhed. Mor havde dækket op med de fine glas, selv om det bare var onsdag. Far så på klokken. – Skal vi sige det nu? spurgte han.' Hvad er det mest sandsynlige?","o":["Forældrene har en vigtig nyhed til børnene","Forældrene har glemt, hvilken ugedag det er","Far skal skynde sig ud til en aftale","Mor er vred, fordi far kom for sent hjem"],"a":"Forældrene har en vigtig nyhed til børnene","r":"De fine glas på en onsdag og farens spørgsmål viser, at noget er planlagt. 'Det' er noget, de har aftalt at sige."},
{"l":7048,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Kulstof findes i flere 'isotoper'. Hvad betyder det?","o":["atomerne har forskelligt antal protoner","atomerne har forskelligt antal neutroner","stoffet findes både som fast stof og gas","stoffet kan kun dannes i et laboratorium"],"a":"atomerne har forskelligt antal neutroner","r":"Isotoper af samme grundstof har lige mange protoner. Ændrer antallet af protoner sig, er det et helt andet grundstof."},
{"l":7071,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hytten var indrettet 'spartansk'. Hvordan så den ud indenfor?","o":["meget rodet og beskidt","meget dyrt og fornemt","meget enkelt uden luksus","meget farverigt og festligt"],"a":"meget enkelt uden luksus","r":"Ordet kommer af bystaten Sparta i det gamle Grækenland, som var kendt for sin strenge, nøjsomme levevis."},
{"l":7091,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Familien i nummer 12 er meget ___.'?","o":["store","stort","storen","stor"],"a":"stor","r":"'Familien' består af flere personer, men ordet står i ental og er fælleskøn. Derfor hedder det 'stor'."},
{"l":7113,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord skal stå i skriftsprog: 'Vi flyttede hertil for ___ år siden.'?","o":["nogle","nogen","noget","hvert"],"a":"nogle","r":"'År' står her i flertal, og sætningen er bekræftende. Derfor skrives 'nogle', selv om de to ord lyder ens i talesprog."},
{"l":7137,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Bogen er lang, men ___ er den spændende.'","o":["tilgengæld","til gengæld","til gengeld","til genkæld"],"a":"til gengæld","r":"Udtrykket skrives i to ord, og 'gengæld' skrives med æ og d."},
{"l":7157,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'For 20 år siden var nørd et skældsord. I dag sætter folk selv ordet på deres profil. Et ord kan altså skifte side uden at skifte bogstaver.' Hvad betyder 'skifte side' her?","o":["At ordet flytter over i et andet sprog","At ordet bruges af de samme mennesker som før","At ordet går fra at være dårligt til at være godt","At ordet får en ny stavemåde i ordbøgerne"],"a":"At ordet går fra at være dårligt til at være godt","r":"Et skældsord er blevet noget, folk er stolte af. Bogstaverne er de samme, men ordet er gået fra at være noget dårligt til noget godt."},
{"l":7179,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket led er 'i går' i: 'Vi var i Tivoli i går.'?","o":["subjekt","direkte objekt","indirekte objekt","adverbialled"],"a":"adverbialled","r":"'I går' siger, hvornår noget skete. Led, der angiver tid, sted eller måde, er adverbialled."},
{"l":7200,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi er glade for at kunne meddele, at vi opgraderer ejendommen med nye dørskilte. I den forbindelse stiger huslejen med 18 procent.' Hvordan er brevet bygget op?","o":["Først noget pænt, og så den dårlige nyhed","Først en dårlig nyhed, og så en tør forklaring","Først en klage, og så en tak til lejerne","Først nogle præcise tal, og så en god nyhed"],"a":"Først noget pænt, og så den dårlige nyhed","r":"'Glade for at kunne meddele' og 'opgraderer' lyder som gode nyheder, men det vigtigste er, at huslejen stiger med 18 procent."},
{"l":7216,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket værk er skrevet af Karen Blixen?","o":["Barndommens gade","Babettes Gæstebud","Stuk","Pelle Erobreren"],"a":"Babettes Gæstebud","r":"'Babettes Gæstebud' er en fortælling af Karen Blixen. Den er også blevet til en kendt film."},
{"l":7238,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning bruger tankestreg rigtigt til at forberede en pointe?","o":["Han havde – kun ét ønske at komme hjem.","Han – havde kun ét ønske at komme hjem.","Han havde kun ét ønske – at komme hjem.","Han havde kun – ét ønske at komme hjem."],"a":"Han havde kun ét ønske – at komme hjem.","r":"Tankestregen giver en pause, lige før det, der er vigtigt, nemlig hvad ønsket er."},
{"l":7258,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvem satte med sine forelæsninger i 1871 gang i det moderne gennembrud i Danmark?","o":["N.F.S. Grundtvig","Adam Oehlenschläger","Klaus Rifbjerg","Georg Brandes"],"a":"Georg Brandes","r":"Georg Brandes holdt i 1871 forelæsninger på Københavns Universitet og krævede en litteratur, der tog samfundets problemer op."},
{"l":7281,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Ella var helt ___ over sin nye cykel.'","o":["begejstret","begejstred","begestret","begejsteret"],"a":"begejstret","r":"Ordet skrives med -gej- og ender på -stret. Der er ikke noget e foran r'et."},
{"l":7300,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Far havde skrevet en lang liste over, hvad der skulle gøres, mens han var væk: hvornår oliefyret skulle efterses, hvilken nøgle der passede til skuret. Der stod ikke et ord om, hvordan vi skulle have det.' Hvad savner fortælleren?","o":["En klarere besked fra far om nøglerne til skuret","Et ord fra far om, hvordan de skulle have det","En mere overskuelig liste over det, der skal gøres","Hjælp fra far til at få oliefyret efterset"],"a":"Et ord fra far om, hvordan de skulle have det","r":"Listen viser, at far tænker på dem, men kun på det praktiske. Sidste sætning viser, hvad fortælleren manglede: 'ikke et ord om, hvordan vi skulle have det'."},
{"l":7322,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket af disse stedord er ikke et personligt stedord?","o":["hun","dem","vores","os"],"a":"vores","r":"'Vores' er et ejestedord, fordi det viser, hvem noget tilhører. De tre andre står i stedet for personer."},
{"l":7340,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Fåreavlere frygter for deres dyr, mens naturvenner glæder sig over, at ulven er tilbage. En forsker peger på, at hegn kan mindske skaderne, men at de er dyre at sætte op.' Hvilken rolle har forskeren i teksten?","o":["Hun afviser fåreavlernes bekymring som en helt grundløs frygt","Hun går ind for at fjerne ulven igen fra Danmark","Hun støtter naturvennerne og deres glæde over ulven","Hun peger på en løsning og dens pris uden at vælge side"],"a":"Hun peger på en løsning og dens pris uden at vælge side","r":"Forskeren nævner både fordelen og ulempen ved hegn. Hun tager ikke stilling til, om ulven bør være her."},
{"l":7362,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer i sætningen: 'Oplysningerne er ___, så du må ikke fortælle dem til andre.'","o":["fortrolige","fortrinlige","forståelige","fornuftige"],"a":"fortrolige","r":"Fortrolige oplysninger må kun nogle få kende. Pas på ikke at blande det sammen med 'fortrinlig', som betyder 'særdeles god'."},
{"l":7384,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Jeg er den mest ærlige mand i byen. Pengene lånte jeg bare, og det er ikke tyveri, når ingen opdager det.' Hvilken slags fortæller er det?","o":["En neutral iagttager uden egne holdninger","En upålidelig fortæller, der pynter på sagen","En alvidende stemme, der står højt over handlingen","En du-fortæller, der taler til læseren"],"a":"En upålidelig fortæller, der pynter på sagen","r":"Han kalder sig ærlig, men hans egne ord afslører det modsatte. Den modsigelse er tegnet på en upålidelig fortæller."},
{"l":7400,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betaler man, når man betaler 'kontingent' i en sportsklub?","o":["en bøde for at komme for sent","et depositum for en nøgle","et fast medlemsbidrag","en entrébillet til hver kamp"],"a":"et fast medlemsbidrag","r":"Kontingent er det beløb, man betaler for at være medlem. Pas på ikke at forveksle det med 'kontinent', som er en verdensdel."},
{"l":7415,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør den, der 'stikker en kæp i hjulet' på en plan?","o":["sætter den hurtigere i gang","forbedrer den med nye ideer","fortæller alle om den i tide","forhindrer, at den lykkes"],"a":"forhindrer, at den lykkes","r":"En kæp i hjulet får vognen til at stoppe. I overført betydning er det at lægge hindringer i vejen for noget."},
{"l":7436,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal den indskudte ledsætning afsluttes med komma: 'Hun sagde at bogen som hun havde lånt var væk.'?","o":["lånt","havde","var","væk"],"a":"lånt","r":"'som hun havde lånt' står inde i at-sætningen og slutter efter 'lånt'."},
{"l":7458,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning er rigtig, når titlen står tæt sammen med navnet?","o":["Eventyrdigteren, H.C. Andersen blev født i Odense.","Eventyrdigteren H.C. Andersen blev født i Odense.","Eventyrdigteren H.C. Andersen, blev født i Odense.","Eventyrdigteren H.C., Andersen blev født i Odense."],"a":"Eventyrdigteren H.C. Andersen blev født i Odense.","r":"'Eventyrdigteren H.C. Andersen' er ét grundled uden ledsætning, så der skal ikke komma."},
{"l":7477,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Efter forestillingen fik skuespillerne en stor ___.'","o":["aplaus","applauz","applaus","applaws"],"a":"applaus","r":"Ordet har dobbelt-p og ender på -aus med s."},
{"l":7499,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Bag huset løb en å, som mine forældre kaldte vores. Den havde været på vej forbi længe før dem og ville blive ved, længe efter.' Hvad vil uddraget sige?","o":["Forældrene passer godt på åen, fordi den er deres","Åen er blevet smallere, siden forældrene flyttede dertil","Fortælleren er stolt af, at familien ejer en å","Åen er ikke rigtig deres, selv om de kalder den det"],"a":"Åen er ikke rigtig deres, selv om de kalder den det","r":"Åen har løbet der længe før forældrene og bliver ved, når de er væk. Så virker det lidt komisk, at de kalder den 'vores'."},
{"l":7513,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord kan erstatte 'substantiel' i sætningen 'Der er sket en substantiel forbedring'?","o":["betydelig","forventet","tilfældig","kortvarig"],"a":"betydelig","r":"En substantiel forbedring er stor og reel. Ordet kommer af 'substans', som betyder indhold."},
{"l":7533,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'En ny ___ viser, at unge sover for lidt.'","o":["undersøggelse","undersøgelse","undersøgelsse","undesøgelse"],"a":"undersøgelse","r":"Ordet kommer af 'undersøge' og får endelsen -else. Der er ét g, og r'et i 'under' skal med."},
{"l":7553,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad angiver ledsætningen i: 'Eftersom døren var låst, kravlede vi ind ad vinduet.'?","o":["tid","betingelse","årsag","formål"],"a":"årsag","r":"'Eftersom' lyder som et ord om tid, men det betyder 'fordi'. Ledsætningen forklarer, hvorfor vi tog vinduet."},
{"l":7575,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad angiver ledsætningen i: 'Han stirrede på os, som om han havde set et spøgelse.'?","o":["betingelse","årsag","tid","sammenligning"],"a":"sammenligning","r":"'Som om' sammenligner måden, han stirrede på, med noget, der ikke nødvendigvis er sket."},
{"l":7597,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvor mange verballed er der i: 'Da vi kom hjem, lavede far mad, og vi dækkede bord.'?","o":["tre","to","fire","fem"],"a":"tre","r":"Verberne 'kom', 'lavede' og 'dækkede' er verballed i hver sin sætning. Hver sætning har ét verballed."},
{"l":7617,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket biord er rigtigt? 'Hun cykler ___ til skole, men i dag tog hun bussen.'","o":["sædvandligvis","sædvanligvis","sedvanligvis","sædvanlivis"],"a":"sædvanligvis","r":"Ordet består af 'sædvanlig' og -vis, skrives med æ og uden d efter n."},
{"l":7636,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Et forslag om lavere fart på Ringvejen deler beboerne. Nogle vil have mere ro og tryghed, andre peger på længere køretid. Politiet tager ikke stilling, men oplyser, at der sidste år skete 11 uheld.' Hvad kan læseren ikke vide ud fra teksten?","o":["Hvor mange uheld der skete sidste år","Hvad tilhængerne af forslaget ønsker","Om lavere fart vil mindske antallet af uheld","Om politiet tager stilling til forslaget"],"a":"Om lavere fart vil mindske antallet af uheld","r":"Der står, hvor mange uheld der skete, men ikke, om der bliver færre med lavere fart. Det kan man kun gætte på."},
{"l":7659,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skemaet viser elever uden fravær i marts. 8.a: 6 ud af 24 elever. 8.b: 6 ud af 20 elever.' Hvilken slutning er rigtig?","o":["8.a har den største andel uden fravær","Andelen er nøjagtig den samme i de to klasser","8.b har flest elever i alt, som er uden fravær","8.b har den største andel uden fravær"],"a":"8.b har den største andel uden fravær","r":"Antallet er det samme, men andelen er 30 procent i 8.b og 25 procent i 8.a. Man skal se på, hvor mange elever der er i hver klasse, og ikke kun på tallet 6."},
{"l":7678,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvorfor skrives 'Mælkevejen' med stort?","o":["Fordi det er et egennavn på en galakse","Fordi alle ord om rummet får stort","Fordi ordet står i bestemt form","Fordi det er et sammensat navneord"],"a":"Fordi det er et egennavn på en galakse","r":"Mælkevejen er navnet på én bestemt galakse, og egennavne skrives med stort."},
{"l":7700,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Læreren siger om to drillepinde, at de er 'en alen af samme stykke'. Hvad mener hun?","o":["at de er lige høje","at de er lige slemme","at de er født samme år","at de er uvenner"],"a":"at de er lige slemme","r":"En alen er et gammelt længdemål for stof. To stykker skåret af samme stof er ens, så udtrykket betyder, at de to er lige gode om det, oftest i negativ forstand."},
{"l":7718,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord skal stå i skriftsprog: 'Hun blev sur uden ___ grund.'?","o":["nogle","noget","nogen","alle"],"a":"nogen","r":"'Grund' står i ental og er fælleskøn, så det hedder 'nogen'. 'Nogle' passer kun foran flertal."},
{"l":7740,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning bruger stedordet forkert i skriftsprog?","o":["Der ligger nogle gamle aviser på bordet.","Er der ikke nogen bager i byen?","Jeg har ikke nogen plan for i aften.","Der ligger nogen gamle aviser på bordet."],"a":"Der ligger nogen gamle aviser på bordet.","r":"'Aviser' er flertal i en bekræftende sætning, så der skal stå 'nogle'. I de to sidste sætninger står et fælleskønsord i ental, og så er 'nogen' rigtigt."},
{"l":7762,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En læge siger i en reklame: 'Efter 30 år i faget ved jeg, hvad der virker.' Hvilken appelform bruger reklamen?","o":["etos","logos","patos","kairos"],"a":"etos","r":"Etos handler om afsenderens troværdighed. Her skal lægens erfaring få modtageren til at stole på budskabet."},
{"l":7784,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En lægebog er fuld af faglig 'terminologi'. Hvad er det?","o":["de lange sætninger i en svær tekst","de faste fagord inden for et område","de tegninger, som forklarer et emne","de kilder, som bogen bygger på"],"a":"de faste fagord inden for et område","r":"Terminologi er de fagudtryk, der bruges inden for et bestemt fag. 'Term' betyder fagord, og '-logi' betyder lære."},
{"l":7799,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Bygningen skal være ___ for kørestolsbrugere.'","o":["tilgænglig","tillgængelig","tilgængelig","tilgengelig"],"a":"tilgængelig","r":"Ordet indeholder 'gænge' med æ, og e'et foran -lig skal med."},
{"l":7816,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Hvad ved Morten om skolemad? Han kan jo ikke engang holde styr på sine sokker.' Hvilken argumentationsfejl er det?","o":["falsk dilemma","cirkelslutning","forhastet generalisering","personangreb"],"a":"personangreb","r":"Skribenten angriber Morten som person i stedet for at svare på hans argumenter om skolemad."},
{"l":7837,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at der er 'korrelation' mellem to ting?","o":["at de følges ad","at den ene altid forårsager den anden","at de er præcis lige store","at de udelukker hinanden"],"a":"at de følges ad","r":"Når den ene ændrer sig, gør den anden det også. Det er ikke det samme som årsag: Issalg og solskoldninger stiger samtidigt, men is giver ikke solskoldning."},
{"l":7855,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Læreren ___ opgaverne, når alle har afleveret.'","o":["vurdere","vurderer","vuderer","vurderrer"],"a":"vurderer","r":"Ordet står i nutid, så navneformen 'vurdere' får et ekstra -r."},
{"l":7876,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hvorfor skal jeg betale til en skole, jeg ikke bruger? Mine børn er voksne. Men jeg bruger heller ikke brandvæsenet hver dag, og jeg er glad for, at det findes.' Hvad gør skribenten i teksten?","o":["Skribenten kritiserer brandvæsenet for at være for dyrt","Skribenten beder sine voksne børn om at betale skat","Skribenten stiller et spørgsmål og svarer selv på det","Skribenten klager over at betale og bliver ved med det"],"a":"Skribenten stiller et spørgsmål og svarer selv på det","r":"Først lyder det som en klage. Men efter 'men' svarer skribenten selv: Man er også glad for brandvæsenet, selv om man ikke bruger det hver dag."},
{"l":7900,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad adskiller især en reportage fra en almindelig nyhedsartikel?","o":["Reportagen er altid kortere end ti linjer","Reportagen må ikke indeholde citater","Reportagen er skrevet af avisens læsere","Reportagen bygger på sanseindtryk fra stedet"],"a":"Reportagen bygger på sanseindtryk fra stedet","r":"Reportagen tager læseren med til stedet med lyde, lugte og stemning, mens nyhedsartiklen er mere nøgtern."},
{"l":7920,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord er komma et krav: 'Da hun så at hunden løb væk råbte hun.'?","o":["væk","hunden","råbte","hun"],"a":"væk","r":"Hele indledningen er ledsætning og slutter efter 'væk'. Komma efter 'så' ville være et valgfrit startkomma."},
{"l":7942,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Billetkontrolløren taler høfligt til en voksen. Hvilket ord skal have stort i 'Har de også en billet, hr. Holm?'","o":["også","de","billet","hr"],"a":"de","r":"Høfligt stedord til én person skrives med stort: De. Ellers kunne det læses som flertal."},
{"l":7964,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad mener man, når man siger, at 'der er ugler i mosen'?","o":["at vejret snart skifter","at natten er ved at falde på","at noget er mistænkeligt","at dyrene er urolige"],"a":"at noget er mistænkeligt","r":"Udtrykket bruges, når man fornemmer, at noget er galt, selv om man ikke kan sige præcis hvad."},
{"l":7982,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad kalder man sprog, der hænger sammen med folks sociale gruppe?","o":["dialekt","idiolekt","fagsprog","sociolekt"],"a":"sociolekt","r":"En sociolekt hænger sammen med social gruppe, mens en dialekt hænger sammen med et geografisk område."},
{"l":8001,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Det hævdes, at børn ikke længere leger ude. Jeg kan oplyse, at jeg i går så tre børn på legepladsen. Så meget for den påstand.' Hvad er svagheden i modargumentet?","o":["Tre børn på en enkelt dag viser ikke, om børn leger ude","Skribenten siger ikke, hvor gamle de tre børn var","Legepladsen ligger ikke i skribentens egen kommune","Påstanden gælder børn og ikke legepladser"],"a":"Tre børn på en enkelt dag viser ikke, om børn leger ude","r":"Påstanden handler om børn i det hele taget. At tre børn legede ude en enkelt dag, ændrer ikke på det."},
{"l":8018,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes de linjer, der gentages efter hver strofe i en sang eller en folkevise?","o":["anslag","omkvæd","replik","slogan"],"a":"omkvæd","r":"Omkvædet vender tilbage igen og igen, så alle kan synge med."},
{"l":8037,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'I et ___ vælger befolkningen sine ledere.'","o":["demokrathi","demmokrati","demokrati","demokrasi"],"a":"demokrati","r":"Ordet kommer fra græsk 'demos' (folk) og 'kratos' (magt). På dansk skrives det med k og t uden h."},
{"l":8060,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er en legende som litterær genre?","o":["En oversigt over kendte danske idrætsfolk","En rimet tale ved en stor bryllupsfest","En kort morsomhed om en dum bonde","En fortælling om en helgens liv og undere"],"a":"En fortælling om en helgens liv og undere","r":"Legender opstod i middelalderen og fortæller om helgener og de undere, de skulle have udført."},
{"l":8081,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord skal stå: 'Jeg ved ikke, hvem ___ har gjort det.'?","o":["der","at","det","om"],"a":"der","r":"'Hvem' er den, der har gjort det, altså grundleddet. Når hv-ordet er grundled i en ledsætning, skal det have 'der' efter sig: 'hvem der', 'hvad der'."},
{"l":8102,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket skuespil af William Shakespeare bygger på fortællingen om Amled, som også findes hos Saxo?","o":["Macbeth","Hamlet","Romeo og Julie","Othello"],"a":"Hamlet","r":"Sagnet om prins Amled findes hos Saxo, og Shakespeares 'Hamlet' bygger på det stof."},
{"l":8121,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad kaldes evnen til at sætte sig ind i andres følelser? Vælg den rigtige stavemåde.","o":["emphati","empathi","empati","emppati"],"a":"empati","r":"Ordet skrives med ét p og uden h på dansk."},
{"l":8144,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Ikaros flyver i den græske myte for tæt på solen med vinger af voks, selvom hans far har advaret ham. Hvad vil myten advare os mod?","o":["At prøve opfindelser, man ikke kender","At rejse langt væk fra sit hjem","At stole for meget på sin far","At blive overmodig og ikke høre efter"],"a":"At blive overmodig og ikke høre efter","r":"Ikaros hører ikke efter sin far og flyver for højt, og så går det galt. Myten advarer mod overmod."},
{"l":8168,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord ligger tættest på 'adækvat' i sætningen 'Eleven gav et adækvat svar'?","o":["passende","overflødigt","hurtigt","morsomt"],"a":"passende","r":"Adækvat betyder dækkende eller tilstrækkeligt i forhold til det, der er brug for. Ordet er almindeligt i faglige tekster og rapporter."},
{"l":8186,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er satire?","o":["En rørende fortælling om tabt kærlighed","Kritik af mennesker eller samfund gennem humor","En neutral gengivelse af en aktuel begivenhed","En tekst, der hylder en konges store dåd"],"a":"Kritik af mennesker eller samfund gennem humor","r":"Satire bruger humor og overdrivelse til at afsløre dumhed eller uret. Den vil gerne have os til at tænke os om."},
{"l":8205,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Man siger 'det lille hus' i stedet for 'toilet'. Hvad kaldes sådan en mild omskrivning?","o":["en metonymi","en hyperbel","en eufemisme","en parabel"],"a":"en eufemisme","r":"'Eu' betyder godt, og 'femi' kommer af det græske ord for at tale. En eufemisme er en pæn omskrivning af noget, der ellers kan virke pinligt eller ubehageligt."},
{"l":8228,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvorfor skal der stå komma efter 'går' i 'Den bog jeg læste i går, var god.'?","o":["Fordi 'går' er et udsagnsord her","Fordi 'bog' er sætningens grundled","Fordi tidsord altid følges af komma","Fordi ledsætningen slutter dér"],"a":"Fordi ledsætningen slutter dér","r":"'jeg læste i går' er en ledsætning uden indledende ord, og efter en ledsætning skal der komma."},
{"l":8250,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør den, der 'kæmper mod vindmøller'?","o":["kæmper forgæves mod en indbildt fjende","arbejder for mere vedvarende energi","holder fast i gamle traditioner på landet","prøver at komme frem i hård modvind"],"a":"kæmper forgæves mod en indbildt fjende","r":"Udtrykket kommer fra romanen om Don Quijote, der forveksler vindmøller med kæmper og går til angreb på dem."},
{"l":8270,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken krig danner baggrund for Herman Bangs roman 'Tine'?","o":["Første Verdenskrig","Krigen i 1864","Englandskrigene","Anden Verdenskrig"],"a":"Krigen i 1864","r":"'Tine' fra 1889 foregår på Als under krigen i 1864, som Bang selv oplevede som barn."},
{"l":8290,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvor ligger Karen Blixens hjem Rungstedlund, der i dag er museum?","o":["På Fyn","På Bornholm","I Nordsjælland","I Vestjylland"],"a":"I Nordsjælland","r":"Rungstedlund ligger i Rungsted ved Øresund i Nordsjælland. Her boede Karen Blixen efter årene i Afrika."},
{"l":8316,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning er rigtig om bilen, der tilhører hr. Schultz?","o":["Hr. Schultz's bil holder udenfor.","Hr. Schultzs bil holder udenfor.","Hr. Schult'z bil holder udenfor.","Hr. Schultz' bil holder udenfor."],"a":"Hr. Schultz' bil holder udenfor.","r":"Navne, der ender på z, følger samme regel som navne på s og x: kun apostrof i genitiv."},
{"l":8334,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken type ledsætning er 'hvor vi mødtes' i: 'Jeg husker ikke, hvor vi mødtes.'?","o":["spørgende ledsætning","relativsætning","at-sætning","adverbialsætning"],"a":"spørgende ledsætning","r":"Her er der ikke noget navneord, ledsætningen hører til. Den rummer spørgsmålet 'Hvor mødtes vi?' og er genstandsled."},
{"l":8359,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Til sin store ___ missede han straffesparket.'","o":["ærgelse","ærgrelse","ærgerlse","ærgerelse"],"a":"ærgrelse","r":"Ordet kommer af 'ærgre' og skrives derfor med gr uden e imellem."},
{"l":8378,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer foran navneordet: 'Vi samlede de ___ æbler op.'?","o":["faldne ned","ned faldne","nedfaldne","falden ned"],"a":"nedfaldne","r":"Foran et navneord skal biordet sættes sammen med tillægsformen og stå først: 'nedfaldne æbler'."},
{"l":8401,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find rigtigt: 'Mødets ___ blev sendt ud før elevrådsmødet.'","o":["dagorden","dagsordren","daksorden","dagsorden"],"a":"dagsorden","r":"Ordet samles med et fuge-s efter 'dag' og ender på 'orden'."},
{"l":8423,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvordan ser en 'kynisk' person på andre mennesker?","o":["han tror, at de kun tænker på sig selv","han tror, at de vil ham det allerbedste","han tror, at de ser ned på ham","han tror, at de ved mere end ham"],"a":"han tror, at de kun tænker på sig selv","r":"Den kyniske person tror ikke på gode motiver og er ofte hård i sit syn på andre. Ordet er i dag negativt ladet."},
{"l":8444,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Vi ___ allerede i januar efter sommeren.'?","o":["længer","længes","længet","længe"],"a":"længes","r":"Verbet 'længes' har altid -s, også i nutid. Det er ikke passiv, for ingen gør noget ved 'vi'."},
{"l":8466,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er det latinske navn for den type stedord, 'hinanden' tilhører?","o":["refleksivt","possessivt","reciprokt","relativt"],"a":"reciprokt","r":"Reciprok betyder gensidig. Refleksivt er tilbagevisende, possessivt er ejestedord, og relativt er henførende."},
{"l":8486,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er en flad karakter i en fortælling?","o":["En person med mange sider, som ændrer sig undervejs","En person, som kun bliver omtalt og aldrig ses","En person, som er fortæller og hovedperson på én gang","En person med få, faste træk, som ikke udvikler sig"],"a":"En person med få, faste træk, som ikke udvikler sig","r":"Flade karakterer er enkle og forudsigelige. Runde karakterer er sammensatte og kan ændre sig."},
{"l":8510,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket tillægsord bøjes slet ikke, hverken i køn eller tal?","o":["lilla","rød","grøn","sort"],"a":"lilla","r":"Det hedder 'en lilla bluse', 'et lilla tæppe' og 'lilla sokker'. 'Sort' får -e i flertal: 'sorte sokker'."},
{"l":8528,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad gør man, når man 'anfægter' en afgørelse?","o":["man støtter den offentligt","man sætter spørgsmålstegn ved den","man bringer den til et arkiv","man ændrer den uden at sige det"],"a":"man sætter spørgsmålstegn ved den","r":"At anfægte er at sige imod og mene, at en afgørelse måske ikke holder. Sætningen 'det anfægter mig ikke' betyder, at noget ikke gør en urolig."},
{"l":8550,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad vil det sige at 'kaste perler for svin'?","o":["at spilde mad, som andre kunne have haft stor glæde af","at købe noget dyrt, som man slet ikke får brug for","at give noget værdifuldt til nogen, der ikke kan værdsætte det","at rose en person, som ikke fortjener nogen ros"],"a":"at give noget værdifuldt til nogen, der ikke kan værdsætte det","r":"Svin har ingen glæde af perler. Udtrykket, der stammer fra Bibelen, bruges om at give noget fint til nogen, der ikke forstår værdien."},
{"l":8575,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er en 'dilettant'?","o":["en ekspert, der ved alt om sit eget fag","en lærling, der er i gang med sin uddannelse","en sanger, der optræder i de store operaer","en amatør, der ikke rigtig har styr på faget"],"a":"en amatør, der ikke rigtig har styr på faget","r":"Ordet kommer af italiensk for 'at more sig'. En dilettant dyrker noget af lyst, men kan det ikke rigtig."},
{"l":8600,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Eleverne skal møde til tiden. Eleverne bør møde til tiden. Eleverne kan møde til tiden.' Hvad er forskellen på de tre sætninger?","o":["Krav, anbefaling og mulighed","Fortid, nutid og fremtid","Ønske, spørgsmål og trussel","Mulighed, krav og anbefaling"],"a":"Krav, anbefaling og mulighed","r":"Mådesudsagnsordene 'skal', 'bør' og 'kan' ændrer styrken. Rækkefølgen betyder noget: Først kravet, så anbefalingen og til sidst muligheden."},
{"l":8627,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'Hun havde en ___ grund til at blive væk: Hun var indkaldt til lægen.'","o":["latent","legitim","lineær","lakonisk"],"a":"legitim","r":"Legitim betyder gyldig eller berettiget. Et lægebesøg er en grund, som man med rette kan henvise til."},
{"l":8650,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Prinsen rejste 'inkognito' gennem landet. Hvad betyder det?","o":["helt alene og uden en eneste vagt","med et stort følge af vagter","uden at folk vidste, hvem han var","for at besøge alle slottene"],"a":"uden at folk vidste, hvem han var","r":"Latin 'incognitus' betyder ukendt. Han skjuler altså, hvem han er, for eksempel under et andet navn."},
{"l":8670,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvordan skrives udtrykket? 'Vi havde købt billetterne ___, så vi slap for køen.'","o":["iforvejen","i forvejn","i forveien","i forvejen"],"a":"i forvejen","r":"Udtrykket skrives i to ord, og 'forvejen' skrives med j."},
{"l":8687,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder det, at en film er 'konventionel'?","o":["Den ligner de fleste andre film","Den ligner slet ikke andre film","Den handler om et stort møde","Den er lavet uden et manuskript"],"a":"Den ligner de fleste andre film","r":"En konvention er en fast skik eller norm. En konventionel film overrasker derfor sjældent sit publikum."},
{"l":8710,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Efter hvilket ord skal der altid stå komma: 'At hun ikke svarede da jeg ringede undrede mig.'?","o":["jeg","ringede","undrede","hun"],"a":"ringede","r":"Hele indledningen er ledsætning og er grundled for 'undrede'. Den slutter efter 'ringede'."},
{"l":8730,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvordan staves ordet? 'Hun er meget ___ og deler gerne ud af sine ting.'","o":["genærøs","jenerøs","generøs","generøss"],"a":"generøs","r":"Ordet kommer fra fransk, begynder med g og slutter på -øs med ét s."},
{"l":8751,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Runealfabetet kaldes futhark. Hvor kommer navnet fra?","o":["fra en gud i nordisk mytologi","fra stedet, hvor runerne blev fundet","fra en konge, der opfandt runerne","fra de første seks runer i rækken"],"a":"fra de første seks runer i rækken","r":"Runerækken begynder med lydene f, u, th, a, r og k. Ligesom 'alfabet' er navnet altså dannet af de første tegn."},
{"l":8773,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"I hvilket af ordene kan d slet ikke høres?","o":["land","gade","dreng","mad"],"a":"land","r":"I 'land' er d stumt. I 'gade' og 'mad' høres det bløde d [ð], og i 'dreng' høres et hårdt d."},
{"l":8792,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er en 'persiflage'?","o":["en højtidelig tale, der hylder en person","en drillende omtale, der gør grin med noget","en kort tekst, der opsummerer en bog","en lang tekst, der beskriver et landskab"],"a":"en drillende omtale, der gør grin med noget","r":"Fransk 'persifler' betyder at gøre nar af. En persiflage gør grin med noget eller nogen for at udstille det, oftest i en tekst."},
{"l":8815,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Forskerne fremlagde en 'tentativ' konklusion. Hvordan var den?","o":["endelig og sikker","forkert og vildledende","foreløbig og forsigtig","lang og indviklet"],"a":"foreløbig og forsigtig","r":"Latin 'tentare' betyder at prøve. Konklusionen er et forsøg og kan ændre sig, når der kommer mere viden."},
{"l":8837,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder det, at en stat er 'suveræn'?","o":["Den er rigere end alle sine naboer","Den har et kongehus som overhoved","Den er medlem af en større union","Den bestemmer selv over sit område"],"a":"Den bestemmer selv over sit område","r":"Suverænitet er den øverste myndighed i et land. Ingen anden stat kan bestemme over en suveræn stat."},
{"l":8860,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad studerer en 'antropolog'?","o":["mennesker og deres kultur","gamle ruiner og oldtidsfund","sprog og deres historie","dyr og deres levesteder"],"a":"mennesker og deres kultur","r":"Antropo- kommer af græsk for menneske. Antropologer undersøger, hvordan mennesker lever sammen i forskellige samfund."},
{"l":8875,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord beskriver en person, der er optaget af sig selv og sin egen fortræffelighed?","o":["altruistisk","narcissistisk","asketisk","lakonisk"],"a":"narcissistisk","r":"Ordet stammer fra den græske myte om Narkissos, der forelskede sig i sit eget spejlbillede i vandet."},
{"l":8895,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find den rigtige form: 'Anmelderen ___ filmens slutning, selvom hun roser skuespillerne.'","o":["kritisere","krittiserer","kritiserer","kritizerer"],"a":"kritiserer","r":"Ordet står i nutid ligesom 'roser', så navneformen 'kritisere' får et ekstra -r."},
{"l":8916,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket led er det egentlige grundled i: 'Der sidder en ugle på taget.'","o":["Der","sidder","på taget","en ugle"],"a":"en ugle","r":"'Der' er et formelt grundled, som blot fylder pladsen. Det er uglen, sætningen handler om, så 'en ugle' er det egentlige grundled."},
{"l":8937,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Alle i klassen har den nye telefon, så det må være den bedste.' Hvilken svaghed har argumentet?","o":["appel til flertallet","personangreb","cirkelslutning","stråmand"],"a":"appel til flertallet","r":"At mange gør noget, beviser ikke, at det er det bedste. Argumentet læner sig kun op ad flertallet."},
{"l":8957,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"En undersøgelse har høj 'validitet'. Hvad betyder det?","o":["Den giver det samme resultat hver gang","Den måler faktisk det, den skal måle","Rigtig mange mennesker har svaret på den","Den kan læses uden forkundskaber"],"a":"Den måler faktisk det, den skal måle","r":"Validitet betyder gyldighed. Spørger man forkert, kan man få mange svar og alligevel ikke måle det, man vil."},
{"l":8972,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er en 'placebo' i et lægemiddelforsøg?","o":["den stærkeste dosis af et nyt stof","en patient, der må stoppe i forsøget","en snydepille uden aktivt stof","en bivirkning, der opstår bagefter"],"a":"en snydepille uden aktivt stof","r":"Placebo er latin for 'jeg vil behage'. Forsøgspersonerne ved ikke, om de har fået den rigtige medicin eller en pille uden virkning."},
{"l":8996,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvad kaldes leddet 'Danmarks hovedstad' i 'København, Danmarks hovedstad, ligger på Sjælland.'?","o":["ledsætning","tiltale","hovedsætning","apposition"],"a":"apposition","r":"En apposition forklarer leddet foran og skilles fra med komma på begge sider."},
{"l":9016,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Jeg arvede min mors hænder. Jeg ser det, når jeg skræller kartofler. Hun holdt tommelfingeren inde ved bladet, selv om hun altid sagde, at man ikke skulle. Nu siger jeg det til min datter.' Hvad er uddragets tema?","o":["At man kommer til at gøre og sige det samme som sine forældre","At man kan komme til skade, når man skræller kartofler","At børn skal lære at lave mad af deres forældre","At mor og datter sjældent taler med hinanden"],"a":"At man kommer til at gøre og sige det samme som sine forældre","r":"Fortælleren holder kniven som moren og siger det samme som moren, selv om moren ikke selv gjorde det, hun sagde. Kartoflerne er bare anledningen."},
{"l":9040,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder det, at en person 'de jure' er ejer af et hus?","o":["Personen er ejer i en kort overgang","Personen er ejer ifølge loven","Personen er ejer sammen med sin familie","Personen er ejer mod sin egen vilje"],"a":"Personen er ejer ifølge loven","r":"De jure er latin for 'efter retten'. Modsætningen er de facto, altså sådan som forholdene er i virkeligheden."},
{"l":9059,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning har rigtig ordstilling, når ledsætningen står i forfeltet?","o":["Da klokken ringede, eleverne gik hjem.","Da ringede klokken gik eleverne hjem.","Da klokken ringede, gik eleverne hjem.","Da klokken ringede eleverne, gik hjem."],"a":"Da klokken ringede, gik eleverne hjem.","r":"Ledsætningen fylder forfeltet, så næste plads er til det bøjede udsagnsord 'gik'. Grundleddet 'eleverne' kommer derfor efter udsagnsordet."},
{"l":9077,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Det var 'inopportunt' at tage emnet op lige dér. Hvad betyder det?","o":["Det var modigt og fortjente stor ros","Det var forbudt ifølge foreningens love","Det var en glimrende og velovervejet idé","Det var upassende på netop det tidspunkt"],"a":"Det var upassende på netop det tidspunkt","r":"In- betyder ikke, og opportun betyder belejlig. Emnet blev altså nævnt på et uheldigt tidspunkt."},
{"l":9100,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad gør en person, der 'fisker i rørte vande'?","o":["skaffer sig en fordel af en urolig situation","forsøger at berolige folk i en svær strid","vælger altid den sværeste vej til målet","bruger sin tid på noget helt uden værdi"],"a":"skaffer sig en fordel af en urolig situation","r":"Når vandet er grumset, er fiskene lettere at fange. Man udnytter altså, at andre er optaget af uroen."},
{"l":9119,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Ordet 'bananer' har tre stavelser. Hvor mange morfemer har det?","o":["tre morfemer","to morfemer","fire morfemer","ét morfem"],"a":"to morfemer","r":"'Banan' er ét morfem, selvom ordet har to stavelser, og '-er' viser flertal. Stavelser og morfemer følger altså ikke hinanden."},
{"l":9137,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Efter nederlaget 'tager anføreren det hele på sin kappe'. Hvad gør hun?","o":["dækker over, hvad der skete","giver dommeren skylden for det","siger, at det er hendes ansvar","trækker sig fra holdet i vrede"],"a":"siger, at det er hendes ansvar","r":"Den, der tager noget på sin kappe, påtager sig ansvaret eller skylden i stedet for at lægge det over på andre."},
{"l":9159,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Om en brand i en lille by findes to kilder: en rapport, som blev skrevet dagen efter af byens vagtmester, og en erindringsbog, som en købmand skrev 40 år senere. Købmanden skriver, at branden var vagtmesterens skyld.' Hvad bør en historiker være særligt opmærksom på?","o":["Rapporten er sikkert usand, fordi den er gammel","Erindringsbogen er rigtig, fordi den er længst","Rapporten må være rigtig, fordi den blev skrevet først","Begge kan have grund til at fortælle det skævt"],"a":"Begge kan have grund til at fortælle det skævt","r":"Vagtmesteren kan forsvare sig selv, og købmanden husker måske forkert eller har en sag. Ingen af kilderne er uden problemer."},
{"l":9180,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Den første del af 'Havde jeg vidst det, var jeg blevet hjemme' er en ledsætning uden bindeord. Hvilket bindeord kan den omskrives med?","o":["hvis","fordi","selvom","mens"],"a":"hvis","r":"Når en ledsætning begynder med udsagnsordet, kan den udtrykke en betingelse. Omskrevet hedder den 'Hvis jeg havde vidst det'."},
{"l":9201,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad var nyt ved H.C. Andersens fortællesprog i forhold til tidens skriftsprog?","o":["Det var skrevet på fine, fremmede sprog","Det lå tæt på talesproget og var fuldt af liv","Det var næsten kun bygget op af lange lister","Det undgik al humor for at virke mere lærd"],"a":"Det lå tæt på talesproget og var fuldt af liv","r":"Andersen skrev, som man talte, med udbrud og direkte henvendelser. Det var usædvanligt i hans tid."},
{"l":9220,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Sætningen 'Hun så manden med kikkerten' kan forstås på to måder. Hvad kaldes den egenskab ved sproget?","o":["autenticitet","aktualitet","ambiguitet","anonymitet"],"a":"ambiguitet","r":"Ambiguitet betyder flertydighed. Her kan både hun og manden have kikkerten."},
{"l":9240,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'I solnedgangen så vi træernes mørke ___ mod himlen.'","o":["siluet","sillhuet","silhouet","silhuet"],"a":"silhuet","r":"Ordet kommer fra fransk og har et stumt h efter l'et, men på dansk skrives det med u."},
{"l":9257,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"En virksomhed skriver 'prisjustering' i stedet for 'prisstigning'. Hvad kaldes sådan et ord?","o":["eufemisme","neologisme","arkaisme","dialekt"],"a":"eufemisme","r":"En eufemisme er et mildere ord for noget ubehageligt. 'Prisjustering' lyder pænere, men dækker over, at tingene bliver dyrere."},
{"l":9280,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Foreningen har 'suspenderet' sin kasserer. Hvad har foreningen gjort?","o":["bedt kassereren om at tjekke regnskabet","fjernet kassereren fra posten for en tid","forhøjet kassererens løn for året","valgt kassereren som ny formand"],"a":"fjernet kassereren fra posten for en tid","r":"Latin 'suspendere' betyder at hænge op. Man sætter kassererens arbejde på pause, mens en sag undersøges."},
{"l":9301,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket forkortelsesord udtales som ét ord og ikke bogstav for bogstav?","o":["EU","FN","NATO","USA"],"a":"NATO","r":"NATO udtales som et almindeligt ord. EU, FN og USA er også dannet af forbogstaver, men her siger man hvert bogstav for sig."},
{"l":9323,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning bruger 'må' om en formodning, altså noget, man regner med er sandt?","o":["Du må gerne låne min blyant i timen.","Vi må ikke løbe på gangen på skolen.","Alle må gå ud, når klokken har ringet.","Asta må være hjemme, for der er lys."],"a":"Asta må være hjemme, for der er lys.","r":"Her regner man ud, at Asta er hjemme, fordi der er lys. I de andre sætninger handler 'må' om, hvad man har lov til."},
{"l":9344,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvordan ser naturalismen på mennesket?","o":["Mennesket er først og fremmest formet af arv og miljø","Mennesket styres af de nordiske guders skjulte planer","Mennesket er frit og kan helt selv vælge sin skæbne","Mennesket kommer til sin ret i drømme og i fantasien"],"a":"Mennesket er først og fremmest formet af arv og miljø","r":"Inspireret af Darwin så naturalisterne mennesket som et produkt af biologi og omgivelser."},
{"l":9362,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Da 'selfie' først dukkede op i dansk, var det et helt nyt ord. Hvad kaldes sådan et ord?","o":["arkaisme","neologisme","palindrom","diminutiv"],"a":"neologisme","r":"Neo- betyder ny, og en neologisme er et nydannet ord. En arkaisme er det modsatte: et gammeldags ord."},
{"l":9385,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Der var engang en kommune, der havde så mange udvalg, at ingen vidste, hvad de hed. Hver gang noget gik galt, nedsatte man et nyt. Og lever de ikke lykkeligt, så nedsætter de endnu.' Hvad opnår teksten ved at bruge eventyrets form?","o":["Den forklarer børn, hvordan en kommune er sat sammen","Den viser, at kommunen i virkeligheden er meget lykkelig","Den gør grin med kommunen ved at lyde som et eventyr","Den fortæller om en virkelig hændelse i en dansk kommune"],"a":"Den gør grin med kommunen ved at lyde som et eventyr","r":"'Der var engang' og 'lever de ikke lykkeligt' kommer fra eventyr. Her handler det om kedelige udvalg, og så bliver det sjovt, og man ser, hvor tosset det er. Det kaldes satire."},
{"l":9405,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find ordet: 'Under den tyske ___ af Danmark fra 1940 til 1945 var der mørklægning om natten.'","o":["okupation","okkupasjon","okkuppation","okkupation"],"a":"okkupation","r":"Ordet har dobbelt-k og ét p og slutter på -tion."},
{"l":9432,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken digter er hovedfigur i dansk barok og kendt for sine salmer?","o":["Thomas Kingo","Ludvig Holberg","Johan Herman Wessel","Adam Oehlenschläger"],"a":"Thomas Kingo","r":"Thomas Kingo levede i 1600-tallet og er kendt for sine barokke salmer."},
{"l":9450,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Hun stolede på sin ___ og valgte den venstre vej.'","o":["intution","intuition","intuisjon","intuission"],"a":"intuition","r":"Ordet indeholder 'intui-' og slutter på -tion."},
{"l":9467,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvordan ser 'et sardonisk smil' ud?","o":["varmt og venligt","genert og usikkert","hånligt og bittert","forvirret og tomt"],"a":"hånligt og bittert","r":"Ordet bruges om en spottende latter eller et smil uden glæde. Det er altså stærkere end almindelig ironi."},
{"l":9490,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvad betyder 'm.fl.' i: 'Ida, Noah m.fl. har meldt sig.'?","o":["Ida og Noah har meldt sig fra igen","Ida og Noah har meldt sig for sidste gang","Kun Ida og Noah har meldt sig i dag","Der er også andre, som har meldt sig"],"a":"Der er også andre, som har meldt sig","r":"'M.fl.' betyder 'med flere', altså at listen fortsætter med andre personer."},
{"l":9510,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find stavemåden: 'Den nye vej bliver bygget af en ___.'","o":["entreprenør","entrepenør","enterprenør","entreprenyr"],"a":"entreprenør","r":"Ordet kommer fra fransk. Husk r'et efter p: entre-pre-nør."},
{"l":9531,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'En gammel matros bor på tredje sal uden udsigt. Hver aften bygger han videre på et skib i en flaske og fortæller om sine år til søs. Da skibet står færdigt, lægger han proppen ved siden af. Et skib skal kunne komme ud, siger han.' Flasken er et symbol. Hvad fortæller den om matrosen?","o":["Han har ikke gjort sit skib helt færdigt endnu","Han længes stadig efter at komme ud på havet","Han er træt af sin lejlighed på tredje sal","Han er stolt af det fine skib, han har bygget"],"a":"Han længes stadig efter at komme ud på havet","r":"Skibet er færdigt, men proppen kommer ikke i, for skibet skal kunne komme ud. Han taler om sine år til søs, så det er havet, han længes efter."},
{"l":9553,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"En novelle hedder 'Stille vand'. Ida er den, der siger mindst i klassen, men derhjemme bygger hun i hemmelighed en robot, der kan tale. Hvad skal titlen fortælle læseren?","o":["At hele novellen foregår ved en stor sø","At der ikke sker noget i teksten","At der gemmer sig mere i Ida, end man tror","At Ida godt kan lide at svømme i søen om sommeren"],"a":"At der gemmer sig mere i Ida, end man tror","r":"Titlen kan læses som et billede: Ida virker stille på overfladen, men der sker en masse nedenunder."},
{"l":9572,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder det, at en folkegruppe lever i 'diaspora'?","o":["Den er i færd med at vende hjem igen","Den har netop fået sit eget selvstændige land","Den bor samlet i en stor hovedstad","Den bor spredt uden for sit oprindelige land"],"a":"Den bor spredt uden for sit oprindelige land","r":"Græsk 'diaspora' betyder spredning. Gruppen holder ofte fast i sin kultur, selvom den bor langt fra sit ophav."},
{"l":9594,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken fejl er der i: 'Lars's søster købte 3,5 kg æbler kl. 10.30.'?","o":["Genitiv af Lars skal kun have apostrof","Decimaltallet skal have punktum i stedet","Klokkeslættet skal skrives med komma","Forkortelsen 'kg' skal have punktum"],"a":"Genitiv af Lars skal kun have apostrof","r":"Navne på s får kun apostrof i genitiv: Lars' søster. Resten af sætningen er rigtig."},
{"l":9611,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'At sige undskyld er let. At sige undskyld uden at tilføje et men er svært.' Hvad mener skribenten om ordet 'men'?","o":["At det gør undskyldningen mere ærlig","At det ofte tager undskyldningen tilbage","At det ikke bør bruges i skriftlig dansk","At det gør undskyldninger lettere at forstå"],"a":"At det ofte tager undskyldningen tilbage","r":"Efter et 'men' følger typisk en forklaring, der flytter skylden. Så er det, som om man tager undskyldningen tilbage."},
{"l":9632,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Bestyrelsen stillede medlemmerne over for et 'fait accompli'. Hvad er det?","o":["et valg mellem to lige gode tilbud","en høring, hvor alle kunne sige deres mening","noget, der allerede var afgjort og gennemført","en fejl, der hurtigt blev rettet igen"],"a":"noget, der allerede var afgjort og gennemført","r":"Fransk 'fait accompli' betyder en fuldbyrdet kendsgerning. Medlemmerne kunne ikke længere nå at sige noget til sagen."},
{"l":9653,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Svensk og norsk skelner mellem ord med ordtoner. Hvilket lydtræk har rigsdansk i stedet?","o":["klik","schwa","rim","stød"],"a":"stød","r":"Rigsdansk har stød, som skiller ord som 'man' og 'mand'. Det er et særligt træk, som man typisk ikke finder i svensk og norsk rigssprog."},
{"l":9675,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Ordet 'rejsende' i 'De rejsende ventede på toget' er dannet af 'rejse' med endelsen '-ende'. Hvilken form er det?","o":["præsens participium","perfektum participium","infinitiv","imperativ"],"a":"præsens participium","r":"Endelsen '-ende' danner præsens participium. Her er det brugt som navneord om personer, der rejser."},
{"l":9696,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad kaldes det, når en sætning i et digt fortsætter over i næste verslinje uden pause?","o":["kiasme","enjambement","epifor","omkvæd"],"a":"enjambement","r":"Ved enjambement løber sætningen ud over linjens slutning. Det kan skabe spænding eller uventede betydninger."},
{"l":9718,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Antallet af unge med en bestemt diagnose er fordoblet på ti år. Det betyder ikke nødvendigvis, at flere er syge. Lægerne er blevet bedre til at opdage tilstanden, og grænsen for diagnosen er ændret.' Hvad skelner teksten mellem?","o":["Unge med diagnose og voksne med samme diagnose","Lægernes viden og deres patienters viden om emnet","Hvor mange der får diagnosen, og hvor mange der er syge","Forskellige former for behandling af tilstanden"],"a":"Hvor mange der får diagnosen, og hvor mange der er syge","r":"Tallet kan stige, fordi lægerne opdager mere, eller fordi grænsen er flyttet, og ikke fordi flere er syge."},
{"l":9737,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Læs: 'Dommeren var ubønhørlig.' Hvad kendetegner dommeren?","o":["Hun glemmer hurtigt, hvad der blev sagt","Hun kan ikke høre, hvad der bliver sagt","Hun dømmer kun i de letteste sager","Hun giver sig ikke, uanset hvem der beder"],"a":"Hun giver sig ikke, uanset hvem der beder","r":"Ordet betyder, at ingen bøn bliver hørt. Det handler altså om ubøjelig hårdhed og ikke om dårlig hørelse."},
{"l":9754,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Et forslag vil give unge indflydelse på kommunens budget. En kommunalpolitiker siger, at unge mangler erfaring. En anden spørger, om erfaring er det eneste, der gør en person i stand til at mene noget.' Hvad sætter den anden politiker spørgsmålstegn ved?","o":["Om erfaring skal afgøre, hvem der må mene noget","Om unge faktisk har mindre erfaring end ældre mennesker","Om forslaget om indflydelse overhovedet er fremsat","Om kommunen har et budget, som unge kan få indflydelse på"],"a":"Om erfaring skal afgøre, hvem der må mene noget","r":"Politikeren diskuterer ikke, om unge mangler erfaring, men om erfaring er det, der skal afgøre sagen."},
{"l":9778,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Hun fandt kassen med hans breve. Hun læste ikke et eneste. Hun bar den ned i kælderen og stillede den, så den kunne findes igen.' Hvad viser sidste led?","o":["At hun er bange for, at nogen skal finde brevene nede i kælderen","At hun ikke er færdig med ham, selv om hun lader brevene ligge","At hun har lovet ham at sende brevene tilbage til ham","At hun allerede har læst brevene engang for længe siden"],"a":"At hun ikke er færdig med ham, selv om hun lader brevene ligge","r":"Hun vil ikke læse brevene, men hun stiller kassen, så den kan findes igen. Hun gemmer dem væk, men ikke helt."},
{"l":9797,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad beskæftiger 'epistemologi' sig med?","o":["hvad der er god og rigtig handling","hvad der gør noget skønt og smukt at se på","hvad viden er, og hvordan vi opnår den","hvordan et samfund bør styres"],"a":"hvad viden er, og hvordan vi opnår den","r":"Græsk 'episteme' betyder viden. Epistemologi kaldes også erkendelsesteori."},
{"l":9820,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kaldes læren om fortolkning og forståelse af tekster?","o":["heuristik","didaktik","kinetik","hermeneutik"],"a":"hermeneutik","r":"Ordet kommer af græsk 'hermeneuein', at fortolke. Heuristik er derimod en metode til at finde løsninger."},
{"l":9840,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilke ord står på pladsen til ubøjede udsagnsord i: 'Ahmed vil gerne have læst bogen inden fredag.'","o":["have læst","vil have","vil gerne","læst bogen"],"a":"have læst","r":"'Vil' er bøjet og står på det bøjede udsagnsords plads. 'Have' og 'læst' er ubøjede former, som i skemaet står efter sætningsadverbialet."},
{"l":9861,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad gør Ludvig Holberg især til grin i komedien 'Erasmus Montanus'?","o":["Fattige børn, der ikke kan læse","Hovmodige studenter med tom lærdom","Købmænd, der handler med udlandet","Bønder, der er flittige og ærlige"],"a":"Hovmodige studenter med tom lærdom","r":"Rasmus Berg kommer hjem som lærd og hovmodig student og vil bevise alt med logiske kneb. Holberg håner den tomme lærdom."},
{"l":9884,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"'Læreren gav Oliver en advarsel' skrives om til 'En advarsel blev givet til Oliver af læreren.' Hvilket led i aktivsætningen er blevet grundled i passiv?","o":["grundleddet","hensynsleddet","genstandsleddet","udsagnsleddet"],"a":"genstandsleddet","r":"'En advarsel' var genstandsled i aktiv og er rykket op som grundled i passiv. Aktivsætningens grundled er blevet til et led med 'af'."},
{"l":9905,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad brugte Søren Kierkegaard ofte, når han lod forskellige livssyn komme til orde?","o":["Replikker fra Holbergs komedier","Rimede sonetter","Avisnotitser","Pseudonymer"],"a":"Pseudonymer","r":"Kierkegaard udgav mange bøger under opdigtede navne. Det gav ham afstand og lod hvert synspunkt tale for sig selv."},
{"l":9925,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er en 'pastiche'?","o":["en efterligning af en forfatters stil","en kort og skarp avisanmeldelse","en bog med forfatterens egne breve","en samling af gamle danske folkeviser"],"a":"en efterligning af en forfatters stil","r":"En pastiche skrives i en anden forfatters stil, ofte som hyldest. Den behøver ikke at være sjov, som en parodi er."},
{"l":9945,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Jeg bærer stenen op ad bakken. / Hver morgen kalder jeg det arbejde. / Hver aften ruller den ned, / og jeg kalder det fyraften.' Hvad udtrykker digtet?","o":["At fysisk arbejde er sundt for krop og sind hver dag","At hverdagen kan føles som det samme igen og igen","At jeg-personen er utilfreds med sin arbejdsgiver","At sten er tunge og bør flyttes ved hjælp af maskiner"],"a":"At hverdagen kan føles som det samme igen og igen","r":"Stenen ruller ned hver aften, så arbejdet bliver aldrig færdigt. Ordene 'arbejde' og 'fyraften' viser, at det handler om en helt almindelig hverdag."},
{"l":9962,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"En journalist spørger 'cui bono' om en ny aftale. Hvad vil journalisten vide?","o":["hvornår aftalen træder i kraft","hvor mange der har læst aftalen","hvem der har fordel af aftalen","hvorfor aftalen er så lang"],"a":"hvem der har fordel af aftalen","r":"Latin 'cui bono' betyder 'til gavn for hvem'. Spørgsmålet skal afsløre, hvem der i virkeligheden tjener på en sag."},
{"l":9984,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning om Astas ord er tegnsat helt rigtigt?","o":["Hvad Asta sagde da hun kom hjem husker jeg ikke, men hun var ked af det.","Hvad Asta sagde, da hun kom hjem husker jeg ikke, men hun var ked af det.","Hvad Asta sagde da hun kom hjem, husker jeg ikke men, hun var ked af det.","Hvad Asta sagde, da hun kom hjem, husker jeg ikke, men hun var ked af det."],"a":"Hvad Asta sagde, da hun kom hjem, husker jeg ikke, men hun var ked af det.","r":"Hele indledningen er ledsætning og skal afsluttes efter 'hjem', og kommaet mellem hovedsætningerne står foran 'men'."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
